(function(){
  const courses=window.COURSES, quizzes=window.QUIZZES;
  let courseCode='MAE101', view='map', selected=0, slideIndex=null, quizIndex=0, quizScore=0, quizAnswered=false;
  const $=s=>document.querySelector(s);
  const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const allItems=coursesKey=>courses[coursesKey].groups.flatMap((g,gi)=>g.items.map((item,ii)=>({...item,group:g.name,gi,ii})));
  const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').replace(/Đ/g,'D').toLowerCase().replace(/[^a-z0-9+]+/g,' ').trim();
  const tokens=s=>normalize(s).split(/\s+/).filter(w=>w.length>2&&!['the','and','voi','cua','mot','nhung','trong','nhieu','hoac','lam','cho','can','nao','giua','dien','what','how','la','gi'].includes(w));
  function renderCourses(){ $('#course-list').innerHTML=Object.entries(courses).map(([code,c])=>`<button class="course-button ${code===courseCode?'active':''}" style="--accent:${c.accent}" data-course="${code}" aria-pressed="${code===courseCode}"><span class="course-dot"></span><span><strong>${code}</strong><small>${escapeHTML(c.name)}</small></span></button>`).join(''); document.querySelectorAll('[data-course]').forEach(b=>b.onclick=()=>selectCourse(b.dataset.course)); }
  function renderHeader(){const c=courses[courseCode];document.documentElement.style.setProperty('--accent',c.accent);$('#course-title').textContent=`${courseCode} · ${c.name}`;$('#course-subtitle').textContent=c.scope;$('#course-counter').textContent=`${allItems(courseCode).length} chủ đề`;}
  function topicStatus(item){if(courseCode==='SDI101m'&&item.source.startsWith('Syllabus'))return 'Theo syllabus · chưa có slide trên máy';if(courseCode==='CEA201'&&courses.CEA201.supplementalNumbers.includes(Number(item.title.split('.')[0])))return 'Chương bổ trợ trong bộ slide';return 'Đã có tài liệu học';}
  function detail(item){return `<span class="tag">${escapeHTML(item.group)} · ${escapeHTML(topicStatus(item))}</span><h3>${escapeHTML(item.title)}</h3><p class="lead">${escapeHTML(item.idea)}</p><p>${escapeHTML(item.details)}</p><dl><dt>Điểm cần nhớ</dt><dd class="formula">${escapeHTML(item.key)}</dd><dt>Ví dụ / cách hiểu</dt><dd>${escapeHTML(item.example)}</dd></dl><div class="source-line">Nguồn đối chiếu: ${escapeHTML(item.source)}</div>`;}
  function renderMap(){const c=courses[courseCode],items=allItems(courseCode);$('#map-root').textContent=courseCode;$('#map-count').textContent=`${c.groups.length} nhánh · ${items.length} nút`;let k=0;$('#map-groups').innerHTML=c.groups.map(g=>`<div class="map-group"><div class="map-group-title">${escapeHTML(g.name)}</div><div class="map-nodes">${g.items.map(i=>`<button class="map-node ${topicStatus(i).startsWith('Đã')?'':'needs-source'} ${k++===selected?'active':''}" data-index="${k-1}" title="${escapeHTML(topicStatus(i))}">${escapeHTML(i.title)}</button>`).join('')}</div></div>`).join('');$('#map-detail').innerHTML=detail(items[selected]||items[0]);document.querySelectorAll('.map-node').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.index);renderMap();if(window.innerWidth<720)$('#map-detail').scrollIntoView({behavior:'smooth',block:'start'});});}
  function renderLearn(){const c=courses[courseCode];$('#chapter-list').innerHTML=c.groups.map(g=>`<div class="chapter-group"><h3>${escapeHTML(g.name)}</h3>${g.items.map(i=>`<details class="chapter"><summary>${escapeHTML(i.title)} <small class="topic-status">${escapeHTML(topicStatus(i))}</small></summary><div class="chapter-body"><p><strong>${escapeHTML(i.idea)}</strong></p><p>${escapeHTML(i.details)}</p><p class="formula">${escapeHTML(i.key)}</p><p>Ví dụ: ${escapeHTML(i.example)}</p><p class="source-line">Nguồn: ${escapeHTML(i.source)}</p></div></details>`).join('')}</div>`).join('');}
  function score(q,t,boost=1){const target=normalize(t),words=tokens(q);let sum=0;for(const w of words){if(target.includes(w))sum+=w.length>5?2:1;}return sum*boost;}
  function renderQuick(){const suggestions={MAE101:['Quy tắc đạo hàm hàm hợp','Ma trận khả nghịch khi nào?','Tích phân xác định là gì?'],CEA201:['Cache hit và miss là gì?','Chu trình fetch execute','Luật Amdahl dùng để làm gì?'],PRF193:['Mảng bắt đầu từ chỉ số mấy?','Truyền tham chiếu khác gì?','Virtual function là gì?'],SDI101m:['Định luật Coulomb','Tiếp giáp p–n hoạt động thế nào?','MOSFET khác BJT ra sao?']};$('#quick-questions').innerHTML=suggestions[courseCode].map(q=>`<button>${escapeHTML(q)}</button>`).join('');$('#quick-questions').querySelectorAll('button').forEach(b=>b.onclick=()=>{$('#question').value=b.textContent;answerQuestion();});}
  async function loadSlides(){if(slideIndex)return slideIndex;try{const r=await fetch('slide-search.json');if(!r.ok)throw Error('unavailable');slideIndex=await r.json();return slideIndex;}catch{slideIndex=[];return slideIndex;}}
  async function answerQuestion(){const q=$('#question').value.trim();if(!q){$('#answer').innerHTML='<p>Hãy nhập câu hỏi trước.</p>';return;}$('#answer').innerHTML='<p>Đang tìm trong tài liệu…</p>';const chapters=allItems(courseCode).map(i=>({item:i,score:score(q,i.title,3)+score(q,i.idea,2)+score(q,i.details+' '+i.key+' '+i.example)})).sort((a,b)=>b.score-a.score);const slides=(await loadSlides()).filter(s=>s.course===courseCode).map(s=>({...s,score:score(q,s.text+' '+s.deck)})).sort((a,b)=>b.score-a.score);const best=chapters[0],related=chapters.filter(x=>x.score>0).slice(0,2),slideMatches=slides.filter(x=>x.score>0).slice(0,3);if((best?.score||0)<2 && !slideMatches.length){$('#answer').innerHTML='<h3>Chưa tìm được căn cứ đủ gần</h3><p>Thử nêu tên khái niệm, công thức hoặc chương. Tôi sẽ không đoán khi tài liệu không có nội dung phù hợp.</p>';return;}let html='<h3>Gợi ý từ tài liệu</h3>';if(related.length){html+=related.map(({item})=>`<div class="match"><strong>${escapeHTML(item.title)}</strong><p>${escapeHTML(item.idea)} ${escapeHTML(item.details)}</p><p><b>Điểm cần nhớ:</b> ${escapeHTML(item.key)}</p><p><b>Ví dụ:</b> ${escapeHTML(item.example)}</p><span class="citation">${escapeHTML(item.source)}</span></div>`).join('');}if(slideMatches.length){html+='<p class="muted">Slide gần với câu hỏi:</p><ul>'+slideMatches.map(s=>`<li>${escapeHTML(s.deck)}, slide ${s.slide}: ${escapeHTML(s.text.slice(0,180))}</li>`).join('')+'</ul>';}html+='<p class="muted">Đây là kết quả tìm kiếm và tóm lược theo tài liệu, không phải câu trả lời do mô hình AI tạo.</p>';$('#answer').innerHTML=html;}
  function renderQuiz(){const set=quizzes[courseCode],q=set[quizIndex];$('#quiz-progress').textContent=`${quizIndex+1}/${set.length} · Đúng ${quizScore}`;$('#quiz-card').innerHTML=`<span class="question-number">CÂU ${quizIndex+1} / ${set.length}</span><h3>${escapeHTML(q.q)}</h3><div class="options">${q.o.map((x,i)=>`<button class="option" data-opt="${i}">${escapeHTML(x)}</button>`).join('')}</div><div id="quiz-feedback"></div><div class="quiz-actions"><button id="quiz-next" style="display:none">${quizIndex===set.length-1?'Xem kết quả':'Câu tiếp theo'}</button><button id="quiz-restart" class="secondary">Làm lại</button></div>`;quizAnswered=false;document.querySelectorAll('.option').forEach(b=>b.onclick=()=>chooseAnswer(Number(b.dataset.opt)));$('#quiz-next').onclick=()=>{if(quizIndex<set.length-1){quizIndex++;renderQuiz();}else{$('#quiz-card').innerHTML=`<h3>Hoàn thành ${set.length} câu</h3><p>Bạn đúng <strong>${quizScore}/${set.length}</strong>. Hãy xem lại các giải thích và nguồn khi cần.</p><button id="quiz-again" class="secondary">Làm lại</button>`;$('#quiz-again').onclick=resetQuiz;}};$('#quiz-restart').onclick=resetQuiz;}
  function chooseAnswer(i){if(quizAnswered)return;quizAnswered=true;const q=quizzes[courseCode][quizIndex];if(i===q.a)quizScore++;document.querySelectorAll('.option').forEach((b,j)=>{b.disabled=true;if(j===q.a)b.classList.add('correct');else if(j===i)b.classList.add('wrong');});$('#quiz-feedback').innerHTML=`<div class="quiz-feedback"><strong>${i===q.a?'Chính xác':'Chưa đúng'}</strong><br>${escapeHTML(q.e)}<br><span class="citation">Nguồn: ${escapeHTML(q.s)}</span></div>`;$('#quiz-next').style.display='inline-block';$('#quiz-progress').textContent=`${quizIndex+1}/${quizzes[courseCode].length} · Đúng ${quizScore}`;}
  function resetQuiz(){quizIndex=0;quizScore=0;renderQuiz();}
  function renderSources(){const c=courses[courseCode],fileList=[...new Set(allItems(courseCode).map(x=>x.source))];const coverage=courseCode==='SDI101m'?'Đã thêm các chủ đề bán dẫn theo lịch 60 buổi của bản syllabus công khai. Phần này chưa có slide 12–28, lab tutorial và sách gốc trên máy, vì vậy các giải thích chỉ là tóm lược nền tảng cần đối chiếu tiếp.':courseCode==='MAE101'?'Có bản tóm tắt 7 trang và mô tả syllabus công khai; chưa có bộ slide đầy đủ hoặc syllabus FLM đúng lớp.':courseCode==='CEA201'?'Trong 21 chương slide có 7 chương không xuất hiện như chương riêng ở mô tả syllabus. Chúng được đánh dấu bổ trợ, không nên tự xem là phạm vi thi.':'Đã lập chỉ mục 7 bộ slide PRF193 và đối chiếu mô tả syllabus công khai; yêu cầu bài tập/thi cụ thể theo lớp cần xem FLM.';$('#source-content').innerHTML=`<article class="source-panel"><h3>Tài liệu đang dùng</h3><p>${escapeHTML(c.sourceNote)}</p><p><strong>Phạm vi:</strong> ${escapeHTML(c.scope)}</p><a href="${c.sourceLink}" target="_blank" rel="noopener noreferrer">Mở bản tra cứu syllabus ↗</a></article><article class="source-panel"><h3>Danh mục nguồn trong bản đồ</h3><ul>${fileList.map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ul></article><article class="source-panel"><h3>Cách dùng khi ôn thi</h3><p>Học ý chính tại đây; với mục có slide trên máy, mở file cùng tên để xem hình và bài tập. Với điểm số, lịch kiểm tra hoặc phạm vi thi, ưu tiên syllabus FLM đúng lớp.</p><p class="warning">SyllaBase là bản tra cứu độc lập tổng hợp từ FLM, không phải trang chính thức của Đại học FPT.</p></article><article class="source-panel"><h3>Độ phủ</h3><p>${escapeHTML(coverage)}</p></article>`;}
  function selectCourse(code){courseCode=code;selected=0;resetQuiz();renderCourses();renderHeader();renderMap();renderLearn();renderQuick();$('#answer').innerHTML='<p>Nhập câu hỏi để tìm trong kiến thức của môn đang chọn.</p>';renderSources();}
  function setView(v){view=v;document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.querySelectorAll('.view').forEach(x=>x.classList.toggle('active',x.id===`${v}-view`));}
  async function copyPrompt(){const q=$('#question').value.trim()||'Hãy giải thích chủ đề tôi đang học';const matches=allItems(courseCode).map(i=>({i,s:score(q,i.title+' '+i.idea+' '+i.details)})).sort((a,b)=>b.s-a.s).slice(0,3);const context=matches.map(({i})=>`${i.title}: ${i.idea} ${i.details} Nguồn: ${i.source}`).join('\n');const prompt=`Tôi học ${courseCode} (${courses[courseCode].name}) tại FPT. Hãy trả lời câu hỏi bằng tiếng Việt dễ hiểu, chỉ dựa trên ngữ cảnh dưới đây. Nếu thiếu căn cứ, nói rõ cần kiểm tra syllabus/slide gốc. Hãy giải thích từng bước và nêu 1 bài tập tự luyện.\n\nCâu hỏi: ${q}\n\nNgữ cảnh:\n${context}`;try{await navigator.clipboard.writeText(prompt);$('#copy-prompt').textContent='Đã sao chép';return true;}catch{$('#copy-prompt').textContent='Không sao chép được';return false;}}
  document.querySelectorAll('.tabs button').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#ask-button').onclick=answerQuestion;$('#question').addEventListener('keydown',e=>{if(e.key==='Enter')answerQuestion();});$('#copy-prompt').onclick=copyPrompt;$('#ai-button').onclick=async()=>{const newTab=window.open('https://chatgpt.com/','_blank');if(newTab)newTab.opener=null;const copied=await copyPrompt();$('#answer').innerHTML=`<p>${copied?'Đã sao chép câu hỏi và ngữ cảnh. Hãy dán vào thẻ ChatGPT vừa mở.':'Trình duyệt không cho sao chép tự động. Hãy dùng nút Chỉ sao chép prompt hoặc tự nhập câu hỏi trong ChatGPT.'}</p>`;if(!newTab)$('#answer').innerHTML+='<p>Trình duyệt đã chặn thẻ mới; hãy mở chatgpt.com thủ công.</p>';};
  selectCourse(courseCode);
})();
